package com.ecotrack.backend.simulation; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/simulation") public class SimulationController{private final SimulationService s;public SimulationController(SimulationService s){this.s=s;}@PostMapping public SimulationDtos.Response simulate(@Valid @RequestBody SimulationDtos.Request r){return s.simulate(r);}}
